import { http, HttpResponse } from 'msw'
import { API_ORIGIN, API_PREFIX } from '@/platform/api/config'
import type { AuditPage, BootstrapResponse, DemoAccount, RoleDto, UserDto, UserPage } from '@/platform/api/types'
import { createDomainHandlers } from './domainHandlers'
import generated from './fixtures/generated.json'

/**
 * A stand-in for the backend so the UI can be built and restyled with the server off.
 *
 * Bootstrap, roles and users come from fixtures generated by the real backend (python -m
 * tools.contract), so the navigation and permissions here cannot drift from it. These handlers are
 * NOT an authority: they do not enforce permissions or business rules, and must never be used to
 * decide what the real system allows.
 */

const BASE = `${API_ORIGIN}${API_PREFIX}`
const DEMO_PASSWORD = 'Unio@Demo2026'

interface Fixtures {
  demoAccounts: DemoAccount[]
  bootstrap: Record<string, BootstrapResponse>
  roles: RoleDto[]
  permissions: string[]
  users: UserPage
}

const fixtures = generated as unknown as Fixtures

const error = (status: number, code: string, message: string) =>
  HttpResponse.json({ code, message, details: {}, correlationId: 'mock-correlation' }, { status })

const SAMPLE_AUDIT: AuditPage = {
  items: [
    ['role.permissions.update', 'ROLE', 'TECHNICIAN', 'SYSTEM_ADMIN', 'Removed parts access for the pilot'],
    ['user.create', 'USER', 'U-TECH4', 'SYSTEM_ADMIN', null],
    ['auth.login', 'USER', 'U-FACILITIES', 'FACILITIES_ADMIN', null],
  ].map(([action, entityType, entityId, actorRole, reason], index) => ({
    id: `mock-audit-${index}`,
    actorId: 'U-MOCK',
    actorRole: actorRole as string,
    action: action as string,
    domain: 'SYSTEM',
    entityType: entityType as string,
    entityId: entityId as string,
    before: {},
    after: {},
    reason: reason as string | null,
    correlationId: null,
    at: new Date(Date.UTC(2026, 0, 1, 9, 0 - index)).toISOString(),
  })),
  page: 0,
  size: 15,
  total: 3,
}

/** Fresh handlers with fresh in-memory state. Tests call this per test so nothing leaks between them. */
export function createHandlers() {
  const roleByEmail = new Map(fixtures.users.items.map((user) => [user.email, user.roleKey]))
  let users: UserDto[] = structuredClone(fixtures.users.items)
  let roles: RoleDto[] = structuredClone(fixtures.roles)

  const tokenFor = (role: string) => `mock.${role}`
  const roleOf = (request: Request) => request.headers.get('authorization')?.replace('Bearer mock.', '') ?? null
  const bootstrapFor = (request: Request) => {
    const role = roleOf(request)
    return role ? fixtures.bootstrap[role] : undefined
  }
  const issue = (role: string) => HttpResponse.json({ accessToken: tokenFor(role), expiresAt: '2030-01-01T00:00:00Z' })

  return [
    http.get(`${BASE}/system/ping`, () => HttpResponse.json({ service: 'unio-mock', database: 'UP', serverTime: new Date().toISOString() })),
    http.get(`${BASE}/auth/demo-accounts`, () => HttpResponse.json(fixtures.demoAccounts)),
    http.post(`${BASE}/auth/demo-login`, async ({ request }) => {
      const { email } = (await request.json()) as { email: string }
      const role = roleByEmail.get(email)
      return role ? issue(role) : error(404, 'NOT_FOUND', 'Demo account was not found.')
    }),
    http.post(`${BASE}/auth/login`, async ({ request }) => {
      const { email, password } = (await request.json()) as { email: string; password: string }
      const role = roleByEmail.get(email)
      return role && password === DEMO_PASSWORD ? issue(role) : error(401, 'INVALID_CREDENTIALS', 'Incorrect email or password.')
    }),
    http.post(`${BASE}/auth/logout`, () => new HttpResponse(null, { status: 204 })),
    http.get(`${BASE}/me/bootstrap`, ({ request }) => {
      const body = bootstrapFor(request)
      return body ? HttpResponse.json(body) : error(401, 'UNAUTHENTICATED', 'Please sign in to continue.')
    }),
    http.get(`${BASE}/me/badges`, () => HttpResponse.json({})),
    http.get(`${BASE}/admin/users`, () => HttpResponse.json({ items: users, page: 0, size: 20, total: users.length })),
    http.post(`${BASE}/admin/users`, async ({ request }) => {
      const body = (await request.json()) as { name: string; email: string; roleKey: string }
      const created: UserDto = {
        id: `U-MOCK-${users.length + 1}`,
        name: body.name,
        email: body.email.toLowerCase(),
        roleKey: body.roleKey,
        departmentId: null,
        status: 'ACTIVE',
        lastLoginAt: null,
        availableActions: [
          { key: 'user.deactivate', label: 'Deactivate' },
          { key: 'user.changeRole', label: 'Change role' },
        ],
        unavailableActions: [{ key: 'user.activate', label: 'Activate', reason: 'This account is already active.' }],
      }
      users = [...users, created]
      return HttpResponse.json(created, { status: 201 })
    }),
    http.patch(`${BASE}/admin/users/:id/status`, async ({ params, request }) => {
      const { status } = (await request.json()) as { status: string }
      users = users.map((user) => (user.id === params.id ? { ...user, status } : user))
      return HttpResponse.json(users.find((user) => user.id === params.id))
    }),
    http.patch(`${BASE}/admin/users/:id/role`, async ({ params, request }) => {
      const { roleKey } = (await request.json()) as { roleKey: string }
      users = users.map((user) => (user.id === params.id ? { ...user, roleKey } : user))
      return HttpResponse.json(users.find((user) => user.id === params.id))
    }),
    http.get(`${BASE}/admin/roles`, () => HttpResponse.json(roles)),
    http.get(`${BASE}/admin/permissions`, () => HttpResponse.json(fixtures.permissions)),
    http.put(`${BASE}/admin/roles/:key`, async ({ params, request }) => {
      const { permissions } = (await request.json()) as { permissions: string[] }
      roles = roles.map((role) => (role.key === params.key ? { ...role, permissions, version: role.version + 1 } : role))
      return HttpResponse.json(roles.find((role) => role.key === params.key))
    }),
    http.get(`${BASE}/audit`, () => HttpResponse.json(SAMPLE_AUDIT)),
    ...createDomainHandlers(),
  ]
}
